<template>
  <div class="ky-page service-page" v-loading="loading">
    <div class="ky-page-header"><h2 class="ky-page-title">{{ staff ? '院内服务任务台' : '院内生活服务' }}</h2><el-button @click="load">刷新服务数据</el-button></div>
