    <div class="ky-card service-toolbar">
      <el-select v-model="profileId" :placeholder="staff ? '选择负责老人（提交服务时必选）' : '选择老人'" style="min-width:240px"><el-option v-for="p in profiles" :key="p.profile_id" :label="p.name || p.elder_name" :value="p.profile_id" /></el-select>
      <el-button v-if="staff" @click="profileId=null">查看全部可管理任务</el-button>
      <el-button type="primary" :disabled="!profileId" @click="openRequest()">申请生活服务</el-button>
      <el-button type="danger" :disabled="!profileId" @click="openCall">呼叫工作人员</el-button>
      <p class="ky-sub">生活服务与健康授权独立。紧急情况请同时使用院内线下求助方式，在线呼叫需工作人员接单。</p>
    </div>
    <div v-if="!profiles.length && !loading" class="ky-card"><el-empty :description="role==='FAMILY' ? '暂无已绑定老人，请先完成绑定' : '暂无可服务的老人档案，请先建立档案或安排照护关系'" /></div>
    <div v-if="staff" class="service-counts"><div class="ky-stat"><div class="ky-stat__label">等待接单</div><strong>{{ dashboard.pending || 0 }}</strong></div><div class="ky-stat"><div class="ky-stat__label">处理中</div><strong>{{ dashboard.in_progress || 0 }}</strong></div><div class="ky-stat"><div class="ky-stat__label">待响应呼叫</div><strong>{{ dashboard.active_calls || 0 }}</strong></div><div class="ky-stat"><div class="ky-stat__label">已升级呼叫</div><strong>{{ dashboard.escalated_calls || 0 }}</strong></div></div>
    <el-tabs v-model="tab" class="ky-card" @tab-change="tabChanged">
      <el-tab-pane label="服务请求" name="requests">
        <div class="service-toolbar"><el-select v-model="filter.status" clearable placeholder="全部状态" @change="loadRequests"><el-option v-for="(label,value) in statuses" :key="value" :label="label" :value="value" /></el-select><el-select v-model="filter.category" clearable placeholder="全部类别" @change="loadRequests"><el-option v-for="c in catalog" :key="c.category" :label="c.name" :value="c.category" /></el-select></div>
        <el-table :data="requests"><el-table-column prop="elder_name" label="老人" width="100" /><el-table-column label="请求内容" min-width="170"><template #default="{row}"><el-tag v-if="row.category==='CALL'" type="danger">{{ row.escalated_at?'呼叫已升级':'优先呼叫' }}</el-tag><div>{{ row.title }}</div></template></el-table-column><el-table-column label="类别"><template #default="{row}">{{ categoryName(row.category) }}</template></el-table-column><el-table-column prop="location" label="地点" /><el-table-column label="状态"><template #default="{row}"><el-tag :type="statusType(row.status)">{{ statuses[row.status] || row.status }}</el-tag></template></el-table-column><el-table-column prop="assigned_name" label="接单人" /><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" @click="openDetail(row)">{{ staff ? '查看 / 处理' : '查看详情' }}</el-button></template></el-table-column></el-table>
        <el-empty v-if="!requests.length" description="暂无符合条件的服务请求" /><el-pagination v-if="total>20" v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="loadRequests" />
      </el-tab-pane>
      <el-tab-pane label="活动与报名" name="activities">
        <el-button v-if="staff" type="primary" @click="activityForm={category:'ENTERTAINMENT',capacity:10,status:'PUBLISHED'};activityDialog=true">发布院内活动</el-button>
        <div class="activity-grid"><article v-for="a in activities" :key="idOf(a,'activity')" class="activity-card"><h3>{{ a.title }}</h3><el-tag>{{ categoryName(a.category) }}</el-tag><p>{{ a.description || '暂无活动说明' }}</p><p>{{ fmtDate(a.start_at) }} 至 {{ fmtDate(a.end_at) }}</p><p>地点：{{ a.location || '待安排' }} · 已报名 {{ a.registered_count || 0 }} / {{ a.capacity }}</p><el-tag v-if="a.status!=='PUBLISHED'" type="info">{{ a.status==='CANCELLED'?'已取消':a.status==='CLOSED'?'报名已关闭':a.status==='DRAFT'?'草稿':a.status==='COMPLETED'?'已结束':a.status }}</el-tag><el-button v-if="a.status==='PUBLISHED'" :disabled="!profileId || a.remaining===0" :loading="acting" @click="registerActivity(a)">为所选老人报名</el-button><el-button @click="showRegistrations(a)">报名 / 出席记录</el-button><el-space v-if="staff && (admin || a.creator_id===userId)" wrap style="margin-top:10px"><el-button v-if="a.status==='DRAFT'" :loading="acting" @click="changeActivity(a,'PUBLISHED')">发布活动</el-button><el-button v-if="a.status==='PUBLISHED'" :loading="acting" @click="changeActivity(a,'CLOSED')">关闭报名</el-button><el-button v-if="a.status!=='CANCELLED'" type="danger" :loading="acting" @click="changeActivity(a,'CANCELLED')">取消活动</el-button></el-space></article></div><el-empty v-if="!activities.length" description="暂无院内活动，工作人员发布后可报名" />
      </el-tab-pane>
      <el-tab-pane label="设备借用" name="equipment">
        <el-button v-if="admin" type="primary" @click="equipmentForm={total:1};equipmentDialog=true">新增设备库存</el-button>
        <el-table :data="equipment"><el-table-column prop="name" label="设备" /><el-table-column prop="description" label="说明" min-width="180" /><el-table-column prop="total" label="总量" /><el-table-column prop="available" label="可借" /><el-table-column prop="damaged" label="损坏" /><el-table-column label="操作" min-width="200"><template #default="{row}"><el-button v-if="admin" link @click="openMaintenance(row)">维护库存</el-button><el-button type="primary" :disabled="!profileId || !row.enabled || row.available<=0" @click="openEquipment(row)">申请借用</el-button></template></el-table-column></el-table><el-empty v-if="!equipment.length" description="暂无设备库存" />
        <p class="ky-sub">申请先形成工单，工作人员接单后才实际出库；库存不足时不会重复借出。</p>
      </el-tab-pane>
      <el-tab-pane label="借还记录" name="loans">
        <el-table :data="loans"><el-table-column prop="elder_name" label="老人" /><el-table-column prop="equipment_name" label="设备" /><el-table-column prop="quantity" label="数量" /><el-table-column label="状态"><template #default="{row}">{{ row.status==='BORROWED'?'借出中':row.status==='RETURNED'?'已归还':row.status }}</template></el-table-column><el-table-column label="借出时间"><template #default="{row}">{{ fmtDate(row.borrowed_at || row.created_at) }}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="staff && row.status==='BORROWED'" type="primary" @click="returningLoan=row;returnForm={damaged:false,note:''};returnDialog=true">登记归还</el-button></template></el-table-column></el-table><el-empty v-if="!loans.length" description="暂无设备借还记录" />
      </el-tab-pane>
      <el-tab-pane :label="'业务通知'+(unread?'（'+unread+'条未读）':'')" name="notifications">
        <article v-for="n in notifications" :key="idOf(n,'notification')" class="notification-card"><div class="service-toolbar"><strong>{{ n.title }}</strong><el-tag :type="n.read_status==='READ'?'info':'warning'">{{ n.read_status==='READ'?'已读':'未读' }}</el-tag><el-button v-if="n.read_status!=='READ'" link type="primary" @click="markRead(n)">标记已读</el-button></div><p>{{ n.content }}</p><small>{{ fmtDate(n.created_at) }}</small><el-button v-if="n.ref_type==='SERVICE_REQUEST'" link @click="openDetail({id:n.ref_id})">查看相关服务</el-button></article><el-empty v-if="!notifications.length" description="暂无生活服务通知" />
      </el-tab-pane>
      <el-tab-pane v-if="admin" label="呼叫响应设置" name="settings"><el-form label-position="top"><el-form-item label="呼叫无人接单时，升级通知管理员的等待秒数"><el-input-number v-model="settings.call_timeout_seconds" :min="15" :max="3600" /></el-form-item><p class="ky-sub">有效范围 15 至 3600 秒。保存后由服务调度使用；前端不会代替工作人员确认已经响应。</p><el-button type="primary" :loading="acting" @click="saveSettings">保存响应设置</el-button></el-form></el-tab-pane>
      <el-tab-pane v-if="admin" label="服务类别配置" name="catalog">
        <el-button type="primary" @click="categoryForm={category:'',name:'',description:'',enabled:true};categoryEditing=false;categoryDialog=true">新增服务类别</el-button><el-table :data="catalog"><el-table-column prop="category" label="标识" /><el-table-column prop="name" label="名称" /><el-table-column prop="description" label="说明" /><el-table-column label="状态"><template #default="{row}">{{ row.enabled===false?'停用':'启用' }}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="categoryForm={...row};categoryEditing=true;categoryDialog=true">编辑</el-button></template></el-table-column></el-table>
      </el-tab-pane>
    </el-tabs>
    <el-dialog v-model="requestDialog" :title="callMode?'呼叫工作人员':'申请生活服务'" width="min(600px,95vw)"><el-form label-position="top"><el-form-item v-if="!callMode" label="服务类别"><el-select v-model="requestForm.category"><el-option v-for="c in normalCategories" :key="c.category" :label="c.name" :value="c.category" /></el-select></el-form-item><el-form-item v-if="!callMode" label="请求标题"><el-input v-model="requestForm.title" maxlength="100" /></el-form-item><el-form-item label="地点 / 房间"><el-input v-model="requestForm.location" maxlength="100" placeholder="如 2 号楼 203 房间" /></el-form-item><el-form-item :label="callMode?'具体需求（可选）':'具体需求'"><el-input v-model="requestForm.description" type="textarea" :rows="3" maxlength="1000" show-word-limit /></el-form-item><el-form-item v-if="!callMode" label="期望时间（可选）"><el-date-picker v-model="requestForm.requested_at" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" /></el-form-item><el-alert type="info" :closable="false" title="请核对老人、地点和需求后提交，建议不会自动变成服务工单。" /></el-form><template #footer><el-button @click="requestDialog=false">取消</el-button><el-button type="primary" :loading="acting" @click="submitRequest">确认提交{{ callMode?'呼叫':'请求' }}</el-button></template></el-dialog>
    <el-dialog v-model="detailDialog" :title="staff ? '院内服务任务处理' : '老人服务申请详情'" width="min(720px,95vw)"><template v-if="detail"><h3>{{ detail.title }}</h3><el-descriptions :column="2" border><el-descriptions-item label="老人">{{ detail.elder_name }}</el-descriptions-item><el-descriptions-item label="状态">{{ statuses[detail.status] || detail.status }}</el-descriptions-item><el-descriptions-item label="地点">{{ detail.location }}</el-descriptions-item><el-descriptions-item label="接单人">{{ detail.assigned_name || '等待接单' }}</el-descriptions-item></el-descriptions><p class="multiline">{{ detail.description }}</p><p v-if="detail.result">处理结论：{{ detail.result }}</p><el-timeline><el-timeline-item v-for="e in detail.events || []" :key="e.id || e.event_id" :timestamp="fmtDate(e.created_at)">{{ e.actor_name || e.operator_name }} · {{ statuses[e.to_status || e.status] || e.action || e.to_status || e.status }}<p>{{ e.result || e.note }}</p></el-timeline-item></el-timeline><el-form v-if="staff && !terminal(detail.status)" label-position="top"><el-form-item label="处理结论（完成或拒绝时必填）"><el-input v-model="transitionResult" type="textarea" :rows="2" maxlength="1000" /></el-form-item></el-form><el-space wrap><el-button v-if="staff && detail.status==='SUBMITTED'" type="primary" :loading="acting" @click="transition('ACCEPTED')">接单</el-button><el-button v-if="staff && detail.status==='ACCEPTED'" type="primary" :loading="acting" @click="transition('IN_PROGRESS')">开始处理</el-button><el-button v-if="staff && detail.status==='IN_PROGRESS'" type="success" :loading="acting" @click="transition('COMPLETED')">完成并留痕</el-button><el-button v-if="staff && detail.status==='SUBMITTED'" type="warning" :loading="acting" @click="transition('REJECTED')">拒绝并说明</el-button><el-button v-if="canCancelRequest(detail)" :loading="acting" @click="transition('CANCELLED')">{{ staff ? '取消任务' : '撤回我的申请' }}</el-button></el-space></template></el-dialog>
    <el-dialog v-model="activityDialog" title="发布院内活动" width="min(620px,95vw)"><el-form label-position="top"><el-form-item label="活动名称"><el-input v-model="activityForm.title" maxlength="100" /></el-form-item><el-form-item label="类别"><el-select v-model="activityForm.category"><el-option v-for="c in normalCategories" :key="c.category" :label="c.name" :value="c.category" /></el-select></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="activityForm.start_at" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" /></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="activityForm.end_at" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" /></el-form-item><el-form-item label="地点"><el-input v-model="activityForm.location" maxlength="100" /></el-form-item><el-form-item label="名额"><el-input-number v-model="activityForm.capacity" :min="1" :max="10000" /></el-form-item><el-form-item label="活动说明"><el-input v-model="activityForm.description" type="textarea" maxlength="1000" /></el-form-item></el-form><template #footer><el-button @click="activityDialog=false">取消</el-button><el-button type="primary" :loading="acting" @click="publishActivity">确认发布</el-button></template></el-dialog>
    <el-dialog v-model="registrationsDialog" :title="selectedActivity?.title+' · 报名与出席'" width="min(650px,95vw)"><el-table :data="registrations"><el-table-column prop="elder_name" label="老人" /><el-table-column label="状态"><template #default="{row}">{{ registrationStatuses[row.status] || row.status }}</template></el-table-column><el-table-column label="操作" min-width="250"><template #default="{row}"><el-space v-if="row.status==='REGISTERED'" wrap><el-button v-if="staff" :disabled="!activityStarted(selectedActivity)" size="small" @click="updateRegistration(row,'ATTENDED')">已出席</el-button><el-button v-if="staff" :disabled="!activityStarted(selectedActivity)" size="small" @click="updateRegistration(row,'ABSENT')">未出席</el-button><el-button v-if="canCancelRegistration(row)" size="small" @click="updateRegistration(row,'CANCELLED')">取消报名</el-button></el-space></template></el-table-column></el-table><el-empty v-if="!registrations.length" description="暂无可见报名记录" /><p v-if="staff && !activityStarted(selectedActivity)" class="ky-sub">活动开始后才能登记实际出席结果。</p></el-dialog>
    <el-dialog v-model="equipmentDialog" title="新增设备库存" width="min(560px,95vw)"><el-form label-position="top"><el-form-item label="设备名称"><el-input v-model="equipmentForm.name" maxlength="100" /></el-form-item><el-form-item label="总数量"><el-input-number v-model="equipmentForm.total" :min="1" :max="10000" /></el-form-item><el-form-item label="说明"><el-input v-model="equipmentForm.description" type="textarea" maxlength="1000" /></el-form-item></el-form><template #footer><el-button type="primary" :loading="acting" @click="saveEquipment">保存设备</el-button></template></el-dialog>
    <el-dialog v-model="borrowDialog" :title="'申请借用 · '+selectedEquipment?.name" width="min(560px,95vw)"><el-form label-position="top"><el-form-item label="数量"><el-input-number v-model="borrowForm.quantity" :min="1" :max="selectedEquipment?.available || 1" /></el-form-item><el-form-item label="使用地点"><el-input v-model="borrowForm.location" maxlength="100" /></el-form-item><el-form-item label="用途"><el-input v-model="borrowForm.description" type="textarea" maxlength="1000" /></el-form-item></el-form><template #footer><el-button type="primary" :loading="acting" @click="submitBorrow">确认申请借用</el-button></template></el-dialog>
    <el-dialog v-model="maintenanceDialog" :title="'维护设备 · '+maintenanceEquipment?.name" width="min(560px,95vw)"><el-form label-position="top"><el-form-item label="总数量"><el-input-number v-model="maintenanceForm.total" :min="0" :max="100000" /></el-form-item><el-form-item label="设备说明"><el-input v-model="maintenanceForm.description" type="textarea" maxlength="1000" /></el-form-item><el-form-item label="允许新借用"><el-switch v-model="maintenanceForm.enabled" /></el-form-item></el-form><p class="ky-sub">总量不能低于已借出与损坏数量；停用后禁止新借用，仍允许归还。</p><template #footer><el-button type="primary" :loading="acting" @click="saveMaintenance">确认更新库存</el-button></template></el-dialog>
    <el-dialog v-model="returnDialog" title="登记设备归还" width="min(560px,95vw)"><p>{{ returningLoan?.equipment_name }} · {{ returningLoan?.quantity }} 件</p><el-form label-position="top"><el-form-item label="本次归还设备是否全部损坏"><el-switch v-model="returnForm.damaged" /></el-form-item><el-form-item label="检查结果 / 备注"><el-input v-model="returnForm.note" type="textarea" maxlength="1000" /></el-form-item></el-form><template #footer><el-button type="primary" :loading="acting" @click="submitReturn">确认归还</el-button></template></el-dialog>
    <el-dialog v-model="categoryDialog" :title="categoryEditing?'编辑服务类别':'新增服务类别'" width="min(560px,95vw)"><el-form label-position="top"><el-form-item label="类别标识"><el-input v-model="categoryForm.category" :disabled="categoryEditing" placeholder="大写字母与下划线，如 COMPANIONSHIP" maxlength="30" /></el-form-item><el-form-item label="显示名称"><el-input v-model="categoryForm.name" maxlength="50" /></el-form-item><el-form-item label="说明"><el-input v-model="categoryForm.description" maxlength="255" /></el-form-item><el-form-item label="启用"><el-switch v-model="categoryForm.enabled" :disabled="['CALL','EQUIPMENT'].includes(categoryForm.category)" /></el-form-item></el-form><template #footer><el-button type="primary" :loading="acting" @click="saveCategory">保存类别</el-button></template></el-dialog>
    
  </div>
</template>
<script setup>
import { ref, computed, onMounted, watch, onBeforeUnmount } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { getUser } from '@/utils/auth'
import { fmtDate, asList } from '@/utils/format'
import { listServiceProfiles,getServiceCatalog,listServiceRequests,createServiceRequest,createServiceCall,getServiceRequest,transitionServiceRequest,listServiceActivities,createServiceActivity,registerServiceActivity,listActivityRegistrations,transitionActivityRegistration,listServiceEquipment,createServiceEquipment,requestServiceEquipment,listServiceLoans,returnServiceLoan,listServiceNotifications,readServiceNotification,createServiceCategory,saveServiceCategory,getServiceDashboard,transitionServiceActivity,updateServiceEquipment,getServiceSettings,saveServiceSettings } from '@/api'
const route=useRoute(),role=getUser()?.role,staff=['CARE','ADMIN'].includes(role),admin=role==='ADMIN',userId=getUser()?.user_id
const profiles=ref([]),profileId=ref(null),catalog=ref([]),requests=ref([]),total=ref(0),page=ref(1),activities=ref([]),equipment=ref([]),loans=ref([]),notifications=ref([]),unread=ref(0),tab=ref(route.query.tab || 'requests'),dashboard=ref({}),filter=ref({status:'',category:''}),loading=ref(false),acting=ref(false),error=ref('')
const statuses={SUBMITTED:'等待接单',ACCEPTED:'已接单',IN_PROGRESS:'处理中',COMPLETED:'已完成',REJECTED:'已拒绝',CANCELLED:'已取消'},registrationStatuses={REGISTERED:'已报名',ATTENDED:'已出席',ABSENT:'未出席',CANCELLED:'已取消'}
const requestDialog=ref(false),callMode=ref(false),requestForm=ref({}),detailDialog=ref(false),detail=ref(null),transitionResult=ref(''),activityDialog=ref(false),activityForm=ref({}),registrationsDialog=ref(false),selectedActivity=ref(null),registrations=ref([]),equipmentDialog=ref(false),equipmentForm=ref({}),borrowDialog=ref(false),selectedEquipment=ref(null),borrowForm=ref({}),returnDialog=ref(false),returningLoan=ref(null),returnForm=ref({}),categoryDialog=ref(false),categoryEditing=ref(false),categoryForm=ref({}),maintenanceDialog=ref(false),maintenanceEquipment=ref(null),maintenanceForm=ref({}),settings=ref({call_timeout_seconds:300})
const normalCategories=computed(()=>catalog.value.filter(c=>!['CALL','EQUIPMENT'].includes(c.category)&&c.enabled!==false))
const requestProfileId=ref(null),borrowProfileId=ref(null)
let viewVersion=0,requestsVersion=0,loansVersion=0,detailVersion=0,registrationsVersion=0
function sameView(id,version){return profileId.value===id && viewVersion===version}
function profileChanged(){viewVersion++;page.value=1;requests.value=[];total.value=0;loans.value=[];detail.value=null;requestDialog.value=false;borrowDialog.value=false;detailDialog.value=false;returnDialog.value=false;registrationsDialog.value=false;error.value='';loadRequests();loadLoans()}
watch(profileId,profileChanged,{flush:'sync'})
onBeforeUnmount(()=>{viewVersion++;requestsVersion++;loansVersion++;detailVersion++;registrationsVersion++})
function idOf(row,kind){return row.id || row[kind+'_id']}
function categoryName(v){return catalog.value.find(c=>c.category===v)?.name || ({CALL:'呼叫',EQUIPMENT:'设备借用'})[v] || v}
function activityStarted(a){return a?.start_at && new Date(a.start_at)<=new Date()}
function terminal(v){return ['COMPLETED','REJECTED','CANCELLED'].includes(v)}
function canCancelRequest(row){return row?.status==='SUBMITTED' && (staff || row.creator_id===userId)}
function canCancelRegistration(row){return row?.status==='REGISTERED' && (staff || row.creator_id===userId) && (staff || !activityStarted(selectedActivity.value))}
function statusType(v){return v==='COMPLETED'?'success':v==='REJECTED'?'danger':v==='SUBMITTED'?'warning':'info'}
async function perform(fn){if(acting.value)return;const version=viewVersion;acting.value=true;try{await fn()}catch(e){if(version===viewVersion){error.value=e.message;ElMessage.error(e.message)}}finally{acting.value=false}}
async function loadRequests(){const id=profileId.value,version=viewVersion,ticket=++requestsVersion;try{const data=await listServiceRequests({profile_id:id||undefined,...filter.value,page:page.value,page_size:20});if(!sameView(id,version)||ticket!==requestsVersion)return;requests.value=asList(data);total.value=data.total??requests.value.length}catch(e){if(sameView(id,version)&&ticket===requestsVersion)error.value=e.message}}
async function load(){loading.value=true;error.value='';try{const [p,c]=await Promise.all([listServiceProfiles(),getServiceCatalog()]);profiles.value=p;catalog.value=c;const requested=Number(route.query.profile_id);if(!profileId.value)profileId.value=p.find(x=>x.profile_id===requested)?.profile_id || (staff?null:p[0]?.profile_id);await Promise.all([loadRequests(),loadActivities(),loadEquipment(),loadLoans(),loadNotifications(),loadDashboard()])}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadDashboard(){if(staff)dashboard.value=await getServiceDashboard()}
async function loadActivities(){activities.value=await listServiceActivities()}
async function loadEquipment(){equipment.value=await listServiceEquipment()}
async function loadLoans(){const id=profileId.value,version=viewVersion,ticket=++loansVersion;try{const rows=await listServiceLoans({profile_id:id||undefined});if(sameView(id,version)&&ticket===loansVersion)loans.value=rows}catch(e){if(sameView(id,version)&&ticket===loansVersion)error.value=e.message}}
async function loadNotifications(){const d=await listServiceNotifications();notifications.value=asList(d);unread.value=d.unread_count||0}
async function tabChanged(){try{if(tab.value==='loans')await loadLoans();if(tab.value==='notifications')await loadNotifications();if(tab.value==='settings')settings.value=await getServiceSettings()}catch(e){error.value=e.message}}
function openRequest(prefill={}){if(!profileId.value)return;requestProfileId.value=profileId.value;callMode.value=false;requestForm.value={category:normalCategories.value[0]?.category || 'OTHER',title:'',description:'',location:profiles.value.find(p=>p.profile_id===profileId.value)?.location || '',...prefill};requestDialog.value=true}
function openCall(){openRequest();callMode.value=true;requestForm.value.description='';}
async function submitRequest(){const id=requestProfileId.value,version=viewVersion;if(!id||id!==profileId.value||!requestDialog.value)return ElMessage.warning('老人已切换，请重新打开申请并核对信息');if(!requestForm.value.location?.trim())return ElMessage.warning('请填写地点或房间');if(!callMode.value&&!requestForm.value.title?.trim())return ElMessage.warning('请填写请求标题');if(!callMode.value&&!requestForm.value.description?.trim())return ElMessage.warning('请填写具体需求');const body={...requestForm.value,profile_id:id},call=callMode.value;await perform(async()=>{if(call)await createServiceCall({profile_id:id,location:body.location,description:body.description});else await createServiceRequest(body);if(!sameView(id,version))return;requestDialog.value=false;await loadRequests();await loadNotifications();ElMessage.success('请求已提交，等待工作人员接单')})}
async function openDetail(row){const id=profileId.value,version=viewVersion,ticket=++detailVersion;await perform(async()=>{const result=await getServiceRequest(idOf(row,'request'));if(!sameView(id,version)||ticket!==detailVersion)return;detail.value=result;transitionResult.value='';detailDialog.value=true})}
async function transition(status){if(!detail.value)return;const row=detail.value,id=profileId.value,version=viewVersion,requestId=idOf(row,'request'),result=transitionResult.value||undefined;if(['COMPLETED','REJECTED'].includes(status)&&!result?.trim())return ElMessage.warning('请填写实际处理结论');if(status==='CANCELLED'){try{await ElMessageBox.confirm('确认取消此服务请求？','取消请求')}catch{return}}if(!sameView(id,version)||detail.value!==row)return;await perform(async()=>{await transitionServiceRequest(requestId,{status,result});const updated=await getServiceRequest(requestId);if(!sameView(id,version)||detail.value!==row)return;detail.value=updated;transitionResult.value='';await Promise.all([loadRequests(),loadLoans(),loadEquipment(),loadNotifications(),loadDashboard()]);ElMessage.success('服务状态已更新')})}
async function publishActivity(){if(!activityForm.value.title?.trim()||!activityForm.value.location?.trim()||!activityForm.value.start_at||!activityForm.value.end_at)return ElMessage.warning('请填写活动名称、地点及起止时间');await perform(async()=>{await createServiceActivity(activityForm.value);activityDialog.value=false;await loadActivities();ElMessage.success('活动已发布')})}
async function changeActivity(a,status){if(status==='CANCELLED'){try{await ElMessageBox.confirm('取消活动后，未出席报名会取消并通知相关人员。确认取消？','取消活动')}catch{return}}await perform(async()=>{await transitionServiceActivity(idOf(a,'activity'),status);await loadActivities();await loadNotifications();ElMessage.success('活动状态已更新')})}
async function registerActivity(a){await perform(async()=>{await registerServiceActivity(idOf(a,'activity'),profileId.value);await loadActivities();await loadNotifications();ElMessage.success('报名成功')})}
async function showRegistrations(a){const id=profileId.value,version=viewVersion,ticket=++registrationsVersion;await perform(async()=>{const rows=await listActivityRegistrations(idOf(a,'activity'));if(!sameView(id,version)||ticket!==registrationsVersion)return;selectedActivity.value=a;registrations.value=rows;registrationsDialog.value=true})}
async function updateRegistration(row,status){const id=profileId.value,version=viewVersion,activity=selectedActivity.value;await perform(async()=>{await transitionActivityRegistration(idOf(row,'registration'),status);const rows=await listActivityRegistrations(idOf(activity,'activity'));if(!sameView(id,version)||selectedActivity.value!==activity)return;registrations.value=rows;await loadActivities();ElMessage.success('报名记录已更新')})}
async function saveEquipment(){if(!equipmentForm.value.name?.trim())return ElMessage.warning('请填写设备名称');await perform(async()=>{await createServiceEquipment(equipmentForm.value);equipmentDialog.value=false;await loadEquipment();ElMessage.success('设备已保存')})}
function openEquipment(row){if(!profileId.value)return;borrowProfileId.value=profileId.value;selectedEquipment.value=row;borrowForm.value={quantity:1,location:profiles.value.find(p=>p.profile_id===profileId.value)?.location || '',description:String(route.query.description || '')};borrowDialog.value=true}
async function submitBorrow(){const id=borrowProfileId.value,version=viewVersion;if(!id||id!==profileId.value||!borrowDialog.value)return ElMessage.warning('老人已切换，请重新打开设备申请');if(!borrowForm.value.location?.trim())return ElMessage.warning('请填写使用地点');const equipmentId=idOf(selectedEquipment.value,'equipment'),body={...borrowForm.value,profile_id:id};await perform(async()=>{await requestServiceEquipment(equipmentId,body);if(!sameView(id,version))return;borrowDialog.value=false;tab.value='requests';await loadRequests();ElMessage.success('设备申请已提交，接单后出库')})}
function openMaintenance(row){maintenanceEquipment.value=row;maintenanceForm.value={total:row.total,description:row.description,enabled:row.enabled};maintenanceDialog.value=true}
async function saveMaintenance(){await perform(async()=>{await updateServiceEquipment(idOf(maintenanceEquipment.value,'equipment'),maintenanceForm.value);maintenanceDialog.value=false;await loadEquipment();ElMessage.success('设备库存已更新')})}
async function saveSettings(){await perform(async()=>{settings.value=await saveServiceSettings(settings.value);ElMessage.success('呼叫响应设置已保存')})}
async function submitReturn(){const id=profileId.value,version=viewVersion,loanId=idOf(returningLoan.value,'loan'),body={...returnForm.value};await perform(async()=>{await returnServiceLoan(loanId,body);if(!sameView(id,version))return;returnDialog.value=false;await loadLoans();await loadEquipment();ElMessage.success('归还已登记')})}
async function markRead(n){await perform(async()=>{await readServiceNotification(idOf(n,'notification'));await loadNotifications()})}
async function saveCategory(){if(!categoryForm.value.name?.trim())return ElMessage.warning('请填写类别名称');await perform(async()=>{if(categoryEditing.value){const {name,description,enabled}=categoryForm.value;await saveServiceCategory(categoryForm.value.category,{name,description,enabled})}else await createServiceCategory(categoryForm.value);categoryDialog.value=false;catalog.value=await getServiceCatalog();ElMessage.success('服务类别已保存')})}
onMounted(async()=>{await load();if(tab.value==='settings')await tabChanged();if(route.query.call&&profileId.value)openCall();else if(route.query.title&&profileId.value){const requested=route.query.category;openRequest({category:normalCategories.value.some(c=>c.category===requested)?requested:'OTHER',title:String(route.query.title),description:String(route.query.description||'')})}})
</script>
<style scoped>
.service-counts{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0}.service-counts strong{font-size:30px}.service-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:16px}.service-toolbar p{flex-basis:100%;margin:0}.notice{margin-bottom:16px}.activity-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-top:18px}.activity-card,.notification-card{border:1px solid #e4e7ed;border-radius:10px;padding:18px;line-height:1.7;margin-bottom:12px}.activity-card h3{margin-top:0}.multiline{white-space:pre-wrap;line-height:1.8}
</style>
